#!/usr/bin/env bash
# GSZ step143 — Own-Inventory engine (admin), modelled on the reseller dashboard's
# Add-Stock. Each product defines credential FIELDS; each plan is a stock pool.
# /admin/inventory: set fields, enable a plan for own stock, bulk add (per-field,
# line-aligned, + ledger vendor/cost). /admin/inventory/manage/:planId: stat cards,
# All/Available/Sold filter, structured credential rows, sold-to, edit/delete,
# bulk-delete, clear, move. Checkout already auto-fulfils source='inventory' plans.
# New routes/adminInventory.js + 2 views. Migration: products.credential_fields,
# inventory_items.fields/account_ref/vendor/cost_pkr. Idempotent; robust health check.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step143-$TS"; TMP=$(mktemp -d)
PATCHED=(server.js views/admin/_shell_top.ejs)
NEW=(routes/adminInventory.js views/admin/inventory.ejs views/admin/inventory_manage.ejs)
echo "==> step143: Own-Inventory engine"
mkdir -p "$BK"; for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"; mkdir -p "$GSZ/routes" "$GSZ/views/admin"
echo "" | base64 -d > "$GSZ/routes/adminInventory.js"
echo ""    | base64 -d > "$GSZ/views/admin/inventory.ejs"
echo ""    | base64 -d > "$GSZ/views/admin/inventory_manage.ejs"
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$TMP/m.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/adminInventory.js"; node --check "$GSZ/server.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/inventory.ejs','views/admin/inventory_manage.ejs','views/admin/_shell_top.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
echo "==> waiting for app to come up"
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE after ${i}s"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step143 OK ✅  Admin → Inventory (/admin/inventory): set a product's fields, turn a plan to own-stock, bulk-add units (per field), and Manage each plan (filter, edit, delete, bulk-delete, move, sold-to). Stocked 'inventory' plans auto-deliver on paid orders."
